bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    switch (keycode) {
    case ARROW:
        if (record->event.pressed) {
            SEND_STRING("->");
        }
        break;
    case STDCC:
        if (record->event.pressed) {
            SEND_STRING("std::");
        }
        break;
    case EMAIL:
        if (record->event.pressed) {
            SEND_STRING("pjmorley@layerzero.com");
        }
        break;
    }
    return true;
};

