void logo_clean(void) {
    uint i = rand() % (sizeof(frames) / sizeof(frames[0]));
    oled_write_raw_P(frames[i], sizeof(frames[i]));
}

void glitch_effect(void) {
    uint sr = (rand() % 8);
    uint br = (rand() % 8);
    if (br > sr) {
        uint tmp = sr;
        sr = br;
        br = tmp;
    }

    oled_scroll_set_area(sr, br);
    oled_scroll_set_speed(rand() % 7);

    if (rand() % 2)
        oled_scroll_right();
    else
        oled_scroll_left();

    // oled_invert(rand() % 2);
}

void logo_animation(void) {
    static uint16_t timer;
    uint16_t te = timer_elapsed(timer);

    if (te < 150) {
        oled_scroll_off();
        logo_clean();
        return;
    }
    if (te < 250) {
        glitch_effect();
        return;
    }
    if (te < 1000) {
        oled_scroll_off();
    }

    if (te > 3000)
        timer = timer_read();

}


// Return true to get the default behavior found in klor.c
bool oled_task_user() {
    if (is_keyboard_master()) {
        return true;
    } else {
        logo_animation();
    }
    return false;
}
